public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            if (n == 0) break;

            int[][] h = new int[n][n];   // horizontal
            int[][] v = new int[n][n];   // vertical
            int[][] d1 = new int[n][n];  // main diagonal \
            int[][] d2 = new int[n][n];  // anti-diagonal /

            int best = 0;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int x = fs.nextInt();
                    if (x == 1) {
                        h[i][j] = (j > 0 ? h[i][j - 1] : 0) + 1;
                        v[i][j] = (i > 0 ? v[i - 1][j] : 0) + 1;
                        d1[i][j] = (i > 0 && j > 0 ? d1[i - 1][j - 1] : 0) + 1;
                        d2[i][j] = (i > 0 && j + 1 < n ? d2[i - 1][j + 1] : 0) + 1;

                        if (h[i][j] > best) best = h[i][j];
                        if (v[i][j] > best) best = v[i][j];
                        if (d1[i][j] > best) best = d1[i][j];
                        if (d2[i][j] > best) best = d2[i][j];
                    }
                }
            }

            out.append(best).append('\n');
        }

        System.out.print(out.toString());
    }
}

