int main(void) {
    int n;

    while (scanf("%d", &n) == 1 && n != 0) {
        int *vert = (int *)calloc(n, sizeof(int));
        int *diag1 = (int *)calloc(2 * n, sizeof(int)); // i-j+n
        int *diag2 = (int *)calloc(2 * n, sizeof(int)); // i+j
        int best = 0;

        for (int i = 0; i < n; i++) {
            int horiz = 0;
            for (int j = 0; j < n; j++) {
                int x;
                scanf("%d", &x);

                if (x == 1) {
                    horiz++;
                    vert[j]++;
                    diag1[i - j + n]++;
                    diag2[i + j]++;

                    if (horiz > best) best = horiz;
                    if (vert[j] > best) best = vert[j];
                    if (diag1[i - j + n] > best) best = diag1[i - j + n];
                    if (diag2[i + j] > best) best = diag2[i + j];
                } else {
                    horiz = 0;
                    vert[j] = 0;
                    diag1[i - j + n] = 0;
                    diag2[i + j] = 0;
                }
            }
        }

        printf("%d\n", best);

        free(vert);
        free(diag1);
        free(diag2);
    }

    return 0;
