                // horizontal
                if (grid[i][j] == 1) {
                    hcnt++;
                    best = max(best, hcnt);
                } else {
                    hcnt = 0;
                }
                // vertical
                if (grid[j][i] == 1) {
                    vcnt++;
                    best = max(best, vcnt);
                } else {
                    vcnt = 0;
                }
            }
        }

        // Check diagonals (top-left to bottom-right)
        for (int start = 0; start < n; ++start) {
            // Diagonals starting from first row
            int cnt = 0;
            for (int i = 0, j = start; i < n && j < n; ++i, ++j) {
                if (grid[i][j] == 1) {
                    cnt++;
                    best = max(best, cnt);
                } else {
                    cnt = 0;
                }
            }
            // Diagonals starting from first column (skip (0,0) already done)
            if (start > 0) {
                cnt = 0;
                for (int i = start, j = 0; i < n && j < n; ++i, ++j) {
                    if (grid[i][j] == 1) {
                        cnt++;
                        best = max(best, cnt);
                    } else {
                        cnt = 0;
                    }
                }
            }
