            // Anti-diagonals starting from first row
            int cnt = 0;
            for (int i = 0, j = start; i < n && j >= 0; ++i, --j) {
                if (grid[i][j] == 1) {
                    cnt++;
                    best = max(best, cnt);
                } else {
                    cnt = 0;
                }
            }
            // Anti-diagonals starting from last column (skip (0,n-1) already done)
