                    max_len = max(max_len, count)
                else:
                    count = 0
                i += 1
                j -= 1
            # start from last column
            i, j = start, n-1
            count = 0
            while i < n and j >= 0:
                if grid[i][j] == 1:
                    count += 1
                    max_len = max(max_len, count)
                else:
                    count = 0
                i += 1
                j -= 1

        results.append(str(max_len))

    sys.stdout.write("\n".join(results))

